  "cause_explanation": "Original answer claims 'High tariff exposure' generally, but cached evidence shows specific 2021 rulings with 'free' duty rates and future variable tariffs (2025/2026) dependent on origin, creating conflict and outdated status relative to 2026 research date.",
  "confidence": "high",
  "remaining_gap": "Specific company applicability not established for general NMC duties beyond specific rulings.",
  "recovery_assessment": "partial_cached_support",
  "evidence": [
    {
      "passage_id": "passage_6a8a89d4be4d1eccf6517634",
      "supporting_excerpt": "The applicable subheading for CSG131-13AW will be 3824.99.3900, Harmonized Tariff Schedule of the United States (HTSUS), which provides for Prepared binders for foundry molds or cores; chemical products and preparations of the chemical or allied industries (including\nthose consisting of mixtures of natural products), not elsewhere specified or included: Other: Other: Other: Mixtures of two or more inorganic compounds: Other.  The rate of duty will be free.",
      "relevance_explanation": "Directly contradicts 'High tariff exposure' claim with specific 'free' duty ruling for NMC from Korea (2021).",
      "company_applicability": "explicit_named_company_effect","temporal_status": "date_not_established"
    },
    {
      "passage_id": "passage_a1812fa3eb99faa9006df6d7",
      "supporting_excerpt": "Since April 2025, a deal effective August 1, 2025, set tariffs at 15%. The 50% tariff rate on aluminum, steel, and copper products remains in place.",
      "relevance_explanation": "Shows variable future tariffs by origin (Japan/Korea) rather than general high exposure.",
      "company_applicability": "national_or_sector_context","temporal_status": "proposal_or_uncertain"
    },
    {
      "passage_id": "passage_5bff7691eccad2c17646be34",
      "supporting_excerpt": "The resulting Cobalt Manganese Nickel Hydroxide, Chemical Abstracts Service Number (“CAS No.”) 189139-63-7 (“semi-finished good A”) classifiable in subheading 2825.90.90, Harmonized Tariff Schedule of the United States (“HTSUS”), will be evenly blended, sieved, de-ironed, packaged, and shipped to Canada.",
      "relevance_explanation": "Demonstrates complex classification (HTSUS) dependent on processing origin rather than simple import duty rates.",
      "company_applicability": "national_or_sector_context","temporal_status": "date_not_established"
    },
    {
      "passage_id": "passage_1a32eeb316c39d8d904021cc",
      "supporting_excerpt": "Freshly refined precursor cathode active material, battery-grade lithium carbonate, NCM hydroxide, and recovered graphite produced through domestic post-treatment refining are not \"shredded lithium-ion battery scrap.\" They are finished battery-grade materials that have completed the refining step and are ready for cell manufacturing.",
      "relevance_explanation": "Clarifies scope of restrictions vs import duties, showing original answer conflated export restrictions with import tariffs.",
      "company_applicability": "national_or_sector_context","temporal_status": "date_not_established"
    }
  ]
}
